#!/usr/bin/env python3
"""Extract selected HUBP1 DCC/tiling/address code, with private capture bindings."""
import argparse
import hashlib
import re
from extract_scaler_geometry import ROOT, REF, COMMIT, extract

OUT = ROOT / 'driver/shim/generated/dc_surface_sequence.inc'


def generate():
    texts = {}
    pieces = ['/* SPDX-License-Identifier: MIT */',
              f'/* PROVENANCE: Linux amdgpu DC, MIT, {COMMIT}.\n'
              ' * Generated by tools/import/extract_surface_sequence.py.\n'
              ' * Original declarations/functions; private REG capture bindings. */',
              '#ifndef BC250_SURFACE_SEQUENCE_FUNCTIONS']
    for name in ('hdmi-link/dc_hw_types.h', 'hubp.h', 'dcn10_hubp.c'):
        raw = (REF / name).read_bytes()
        text = raw.decode().replace('\r\n', '\n')
        texts[name] = text
        pieces += [text[:text.index('*/') + 2], f'/* {name}, sha256 {hashlib.sha256(raw).hexdigest()} */']
    for name, decls in (
        ('hdmi-link/dc_hw_types.h', ['union large_integer', 'enum dc_plane_addr_type',
                                    'struct dc_plane_address', 'enum swizzle_mode_values',
                                    'enum surface_pixel_format']),
        ('hubp.h', ['enum hubp_ind_block_size']),
    ):
        for decl in decls:
            found = re.findall(r'^' + decl + r' \{.*?^\};', texts[name], re.M | re.S)
            if len(found) != 1:
                raise ValueError(decl)
            if decl == 'struct dc_plane_address':
                pieces.append('#define PHYSICAL_ADDRESS_LOC union large_integer')
            pieces.append(found[0])
    functions = [extract(texts['dcn10_hubp.c'], name) for name in (
        'hubp1_dcc_control', 'hubp1_program_tiling', 'hubp1_program_surface_flip_and_addr')]
    bindings = {}
    for function in functions:
        for kind, args in re.findall(r'\b(REG_(?:SET|UPDATE(?:_[2468])?))\((.*?)\);', function, re.S):
            args = [v.strip() for v in args.split(',')]
            reg, pairs = args[0], args[2:] if kind == 'REG_SET' else args[1:]
            for field in pairs[::2]:
                if field in bindings and bindings[field] != reg:
                    raise ValueError('Ambiguous field ' + field)
                bindings[field] = reg
    regs = sorted(set(bindings.values()))
    pieces += ['enum { ' + ', '.join(regs) + ', SURFACE_SEQUENCE_REG_COUNT };']
    header = (ROOT / 'third_party/linux-amdgpu/dcn_2_0_1_sh_mask.h').read_text()
    for field, reg in sorted(bindings.items()):
        found = re.findall(r'^#define ((?:HUBP0|HUBPREQ0)_' + re.escape(reg + '__' + field + '_MASK') + r')\s', header, re.M)
        if len(found) != 1:
            raise ValueError('Unresolved DCN201 field ' + reg + '/' + field)
        pieces.append('#define MASK_' + field + ' ' + found[0])
        other = found[0].replace('HUBP0_', 'HUBP1_').replace('HUBPREQ0_', 'HUBPREQ1_')
        pieces.append(f'_Static_assert({found[0]} == {other}, "surface instance mask mismatch");')
    pieces += ['#else']
    for function in functions:
        pieces += ['/* Adapter linkage declaration. */\nstatic ' + function[:function.index('\n{')] + ';', function]
    pieces.append('#endif')
    return ('\n\n'.join(pieces) + '\n').encode()


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    expected = generate()
    if args.check:
        if OUT.read_bytes() != expected:
            raise SystemExit('Surface sequence extraction mismatch')
    else:
        OUT.write_bytes(expected)
    print('Surface sequence extraction OK')
